cypress_script:
describe('Links API Response Handling', () => {
  it('should navigate to Home when clicking the Home link', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('#simpleLink').click();
    cy.url().should('eq', 'https://demoqa.com/');
  });
  it('should not navigate when clicking the Bad Request link', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('#bad-request').click();
    cy.url().should('eq', 'https://demoqa.com/links');
    cy.get('#bad-request').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Links API Response Handling', () => {
  test('should navigate to Home when clicking the Home link', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('#simpleLink');
    await expect(page).toHaveURL('https://demoqa.com/');
  });
  test('should not navigate when clicking the Bad Request link', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('#bad-request');
    await expect(page).toHaveURL('https://demoqa.com/links');
    await expect(page.locator('#bad-request')).toBeVisible();
  });
});
